<template>
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.3/css/all.min.css"
        referrerpolicy="no-referrer"/>

  <div class="tabs">
    <ul class="tabs_header">
      <li class="tab_header" v-for="tab in tabTitles" :key="tab.title" :class="{selectedFugi: selectedTitle === 'Fugitive', selected: tab.title === selectedTitle}" @click="selectedTitle = tab.title">
        {{ tab.title }}
      </li>
    </ul>
    <slot/>
  </div>
</template>

<script>
import { ref, provide } from 'vue';

export default {
  name: "LoadoutsTabsWrapper",
  setup(props, {slots}) {
    const tabTitles = ref(slots.default().map((tab) => tab.props))
    const selectedTitle = ref(tabTitles.value[0].title)

    provide("selectedTitle", selectedTitle)
    return {
      selectedTitle,
      tabTitles
    }
  }
}
</script>

<style scoped lang="scss">
.tabs {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
}

.fas {
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 20px;
}

.logo {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 5px  0px 5px 0px;

  background: #2d6ae3;

  img {
    width: 50px;
  }
}

.tabs_header {
  display: flex;
  height: 60px;
  width: 100%;
  justify-content: center;
  align-items: center;
  color: $sago-gray2;
  border-bottom: 1px solid $sago-gray2;
  font-weight: bold;

  .selected {
    transition: all 0.4s;
    transition-property: color,text-shadow;
    color: #fff;
    border-bottom: 1px solid #2d6ae3;
    text-shadow: 0 0 5px #fff;
  }

  .selectedFugi {
    border-color: #cb4040;
  }

  .tab_header {
    margin: 0px 10px -9px 10px;
    display: grid;
    justify-content: center;
    align-items: center;
    height: 50px;
    cursor: pointer;
    font-size: 20px;
  }
}

</style>