<template>
  <div class="wrapper">
    <div class="top">
      DM Arenas
    </div>
    <div class="bottom">
      <div class="lobbies">
        <div v-for="lobby in games" :key="lobby.id" :class="['lobby']"
             :style="{ background: 'linear-gradient(rgba(25, 23, 36, 0.9),rgba(25, 23, 36, 0.9)),  url(' + lobby.background + ') no-repeat center center', backgroundSize: 'cover' }">
          <div class="info">
            <div class="lobby-name">{{ lobby.name }}<i v-show="lobby.password" class="fas fa-lock lobby-locked"></i></div>
            <div class="lobby-info">
              <div v-show="lobby.gamemode" class="lobby-gamemode">{{ lobby.gamemode }}</div>
              <div v-show="lobby.description" class="lobby-description">{{ lobby.description }}</div>
            </div>
          </div>
          <div class="players">
            <span class="lobby-stats">{{ lobby.players }}/{{ lobby.maxplayers }}</span><i class="fas fa-users"></i>
          </div>
          <div class="join">
            <button :class="['join-button', { current: currentMinigame === lobby.id, full: lobby.players === lobby.maxplayers && currentMinigame !== lobby.id }]"
                    @click="joinMinigame(lobby.id, lobby.name, lobby.players, lobby.maxplayers, lobby.password)" :disabled="lobby.players === lobby.maxplayers || currentMinigame === lobby.id">
              <div v-if="currentMinigame === lobby.id">Joined</div>
              <div v-else-if="lobby.maxplayers === 0">N/A</div>
              <div v-else-if="lobby.players === lobby.maxplayers">Full</div>
              <div v-else>Join</div>
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "MinigamesTab",
  methods: {
    joinMinigame(id) {
      // eslint-disable-next-line no-undef
      mp.trigger('RequestJoinMinigame', id);
    }
  },
  data() {
    return {
      currentMinigame: null,
      games: [{
        id: 0,
        name: 'Opasan Toranj',
        background: 'https://live.staticflickr.com/7526/16232917915_3ef3d4ab4d_b.jpg',
        gamemode: 'DM',
        description: 'Very dangerous',
        players: 3,
        maxplayers: 10
      },]
    }
  }
}
</script>

<style lang="scss">
.lobby-locked {
  color: $sago-gray2;
  font-size: 20px;
  margin-left: 10px;
}

.lobby-pass-confirm {
  background: none;
  border: 2px solid #2d6ae3;
  color: #f1f1f1;
  padding: 10px 30px;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.4s;
  margin-right: 10px;

  &:hover {
    background: #2d6ae3;
  }

  &:focus {
    border: 2px solid #2d6ae3;
    outline: none;
    background: #2d6ae3;
  }
}

.lobby-pass-cancel {
  background: none;
  border: 2px solid $sago-gray;
  color: $sago-gray;
  padding: 10px 30px;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.4s;
  margin-left: 10px;
  font-weight: bold;

  &:hover {
    background: $sago-gray;
    color: #fff;
  }

  &:focus {
    border: 2px solid $sago-gray;
    outline: none;
    background: $sago-gray;
    color: #fff;
  }
}

.lobby-pass-input {
  border: none !important;
  border-radius: 0px !important;
}
</style>

<style scoped lang="scss">

/* width */
::-webkit-scrollbar {
  width: 7px;
}

/* Track */
::-webkit-scrollbar-track {
  background: none;
}

/* Handle */
::-webkit-scrollbar-thumb {
  background: $lscc-blue;
}

.wrapper {
  display: flex;
  flex-direction: column;
}

.top {
  height: 60px;
  display: flex;
  align-items: center;
  padding: 20px 0px 20px 30px;
  font-size: 22px;
  color: #fff;
  border-bottom: 1px solid $sago-gray2;
}

.lobbies {
  display: grid;
  grid-template-columns: 50% 50%;
  width: 100%;
  height: 100%;
  justify-content: center;
  align-items: center;
  overflow-y: auto;
  max-height: 700px;
}

.lobby {
  display: flex;
  border: 2px solid $sago-dark;
  height: 130px;
  margin: 10px 10px;

  .info {
    flex: 0.6;
    display: grid;
    padding: 10px 0px 0px 30px;
    color: #fff;
    font-weight: 100;
  }

  .lobby-name {
    color: #fff;
    font-size: 25px;
    font-weight: 300;
  }

  .players {
    flex: 0.3;
    font-size: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    color: #fff;

    .lobby-stats {
      margin-right: 7px;
      font-weight: 100;
    }

    .fas {
      color: $sago-gray2;
      font-size: 25px;
    }
  }

  .join {
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 0.4;
  }

  .join-button {
    background: none;
    border: 2px solid #2d6ae3;
    color: #fff;
    padding: 10px 30px;
    font-size: 20px;
    cursor: pointer;
    transition: background 0.4s;

    &:hover {
      background: #2d6ae3;
    }
  }

  .current {
    background: #2d6ae3;
    border: 2px solid #2d6ae3;

    &:hover {
      background: #2d6ae3;
    }
  }

  .full {
    border: 2px solid $sago-gray2;
    color: $sago-gray2;
    cursor: default;

    &:hover {
      background: none;
    }
  }
}
</style>