<template>
  <div class="wrapper">
    <div class="top">
      Lobbies
    </div>
    <div class="bottom">
      <div class="lobbies">
        <div v-for="lobby in lobbies" :key="lobby.id" :class="['lobby']"
             :style="{ background: 'linear-gradient(rgba(25, 23, 36, 0.9),rgba(25, 23, 36, 0.9)),  url(' + lobby.background + ') no-repeat center center', backgroundSize: 'cover' }">
          <div class="info">
            <div class="lobby-name">{{ lobby.name }}<div class="lobby-locked"><i v-show="lobby.password" class='bx bx-lock-alt' ></i></div></div>
            <div class="lobby-info">
              <div v-show="lobby.gamemode" class="lobby-gamemode">{{ lobby.gamemode }}</div>
              <div v-show="lobby.description" class="lobby-description">{{ lobby.description }}</div>
            </div>
          </div>
          <div class="players">
            <span class="lobby-stats">{{ lobby.players }}/{{ lobby.maxplayers }}</span><i class="fas fa-users"></i>
          </div>
          <div class="join">
            <button :class="['join-button', { current: currentLobby === lobby.id, full: lobby.players === lobby.maxplayers && currentLobby !== lobby.id }]"
                    @click="joinParty(lobby.id, lobby.name, lobby.players, lobby.maxplayers, lobby.password)" :disabled="lobby.players === lobby.maxplayers || currentLobby === lobby.id">
              <div v-if="currentLobby === lobby.id">Joined</div>
              <div v-else-if="lobby.maxplayers === 0">N/A</div>
              <div v-else-if="lobby.players === lobby.maxplayers">Full</div>
              <div v-else>Join</div>
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "LobbiesTab",
  methods: {
    joinParty(id, name, players, maxplayers, password) {
      if (!password) {
        // eslint-disable-next-line no-undef
        mp.trigger('PutPlayerInLobby', id, "");
        return;
      }
      // eslint-disable-next-line no-undef
      mp.trigger('MenuToggleTyping', true);
      // eslint-disable-next-line no-undef
      Swal.fire({
        title: 'Lobby Password',
        input: 'password',
        inputAttributes: {
          autocapitalize: 'off'
        },
        showCancelButton: true,
        confirmButtonText: 'Join',
        buttonsStyling: false,
        customClass: {
          confirmButton: 'lobby-pass-confirm',
          cancelButton: 'lobby-pass-cancel',
          input: 'lobby-pass-input',
        },
      }).then((result) => {
        // eslint-disable-next-line no-undef
        mp.trigger('MenuToggleTyping', false);
        if (result.isConfirmed) {
          // eslint-disable-next-line no-undef
          mp.trigger('PutPlayerInLobby', id, result.value);
        }
      })
    }
  },
  data() {
    return {
      currentLobby: null,
      lobbies: [{
        id: 0,
        name: 'Copchase 1',
        background: 'https://live.staticflickr.com/7526/16232917915_3ef3d4ab4d_b.jpg',
        gamemode: 'Copchase',
        password: 'sex',
        players: 11,
        maxplayers: 25
      }, {
        id: 1,
        name: 'Copchase 2',
        description: 'Optional description',
        background: 'https://wallpapercave.com/wp/wp4501529.jpg',
        gamemode: 'Copchase',
        players: 14,
        maxplayers: 35
      }, {
        id: 2,
        name: 'Copchase 3',
        background: 'https://wallpapers-hub.art/wallpaper-images/192181.jpg',
        gamemode: 'Copchase',
        players: 8,
        maxplayers: 20
      }, {
        id: 3,
        name: 'Copchase 4',
        background: 'https://c4.wallpaperflare.com/wallpaper/519/763/782/gta-5-background-desktop-wallpaper-preview.jpg',
        gamemode: 'Copchase',
        players: 15,
        maxplayers: 15
      },]
    }
  }
}
</script>

<style scoped lang="scss">
.lobby-locked {
  color: $sago-gray2;
  font-size: 25px;
  margin-top: 4px;
}

.lobby-pass-confirm {
  background: none;
  border: 2px solid #2d6ae3;
  color: #f1f1f1;
  padding: 10px 30px;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.4s;
  margin-right: 10px;
  font-weight: bold;

  &:hover {
    background: #2d6ae3;
  }

  &:focus {
    border: 2px solid #2d6ae3;
    outline: none;
    background: #2d6ae3;
  }
}

.lobby-pass-cancel {
  background: none;
  border: 2px solid $sago-gray;
  color: $sago-gray;
  padding: 10px 30px;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.4s;
  margin-left: 10px;
  font-weight: bold;

  &:hover {
    background: $sago-gray;
    color: #fff;
  }

  &:focus {
    border: 2px solid $sago-gray;
    outline: none;
    background: $sago-gray;
    color: #fff;
  }
}

.lobby-pass-input {
  border: none !important;
  border-radius: 0px !important;
}

/* width */
::-webkit-scrollbar {
  width: 7px;
}

/* Track */
::-webkit-scrollbar-track {
  background: none;
}

/* Handle */
::-webkit-scrollbar-thumb {
  background: $lscc-blue;
}

.wrapper {
  display: flex;
  flex-direction: column;
}

.top {
  height: 60px;
  display: flex;
  align-items: center;
  padding: 20px 0px 20px 30px;
  font-size: 22px;
  color: #fff;
  border-bottom: 1px solid $sago-gray2;
}

.lobbies {
  display: grid;
  grid-template-columns: 50% 50%;
  width: 100%;
  height: 100%;
  justify-content: center;
  align-items: center;
  overflow-y: auto;
  max-height: 700px;
}

.lobby {
  display: flex;
  border: 2px solid $sago-dark;
  height: 130px;
  margin: 10px 10px;

  .info {
    flex: 0.6;
    display: grid;
    padding: 10px 0px 0px 30px;
    color: #fff;
    font-weight: 300;
  }

  .lobby-name {
    color: #fff;
    font-size: 25px;
    font-weight: 300;
    display: flex;
  }

  .players {
    flex: 0.3;
    font-size: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    color: #fff;

    .lobby-stats {
      margin-right: 7px;
      font-weight: 300;
    }

    .fas {
      color: $sago-gray2;
      font-size: 25px;
    }
  }

  .join {
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 0.4;
  }

  .join-button {
    background: none;
    border: 2px solid #2d6ae3;
    color: #fff;
    padding: 10px 30px;
    font-size: 20px;
    cursor: pointer;
    transition: background 0.4s;

    &:hover {
      background: #2d6ae3;
    }
  }

  .current {
    background: #2d6ae3;
    border: 2px solid #2d6ae3;

    &:hover {
      background: #2d6ae3;
    }
  }

  .full {
    border: 2px solid $sago-gray2;
    color: $sago-gray2;
    cursor: default;

    &:hover {
      background: none;
    }
  }
}
</style>