<template>
  <div class="vehicles">
    <div v-for="vehicle in vehicles" :key="vehicle.model" :class="['vehicle']"
         :style="{ background: 'linear-gradient(rgba(25, 23, 36, 0.9),rgba(25, 23, 36, 0.9)),  url(' + vehicle.background + ') no-repeat center center', backgroundSize: 'cover' }">
      <div class="info">
        <div class="vehicle-name">{{ vehicle.name }}</div>
        <div class="vehicle-info">
          <div v-show="vehicle.price" class="stat"><i class='bx bxs-dollar-circle'></i>{{ vehicle.price }}</div>
          <div v-show="vehicle.energy" class="stat"><i class='bx bxs-bolt-circle'></i>{{ vehicle.energy }}
          </div>
        </div>
      </div>
      <div class="join">
        <button @click="selectBuy(vehicle.model)" :class="{ selectedButton: selectedModel === vehicle.model, selectButton: !vehicle.locked }" :disabled="selectedModel === vehicle.model" class="buyButton">
          <template v-if="selectedModel === vehicle.model">
            Selected
          </template>
          <template v-else-if="vehicle.locked">
            Buy
          </template>
          <template v-else>
            Select
          </template>
        </button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "PoliceVehicles",
  methods: {
    selectBuy(model) {
      // eslint-disable-next-line no-undef
      mp.trigger('MenuSelectVehicle', model, 1);
    },
  },
  data() {
    return {
      selectedModel: null,
      vehicles: [{
        model: 'f620',
        name: 'f620',
        background: 'https://i.imgur.com/N9RMeyx.png',
        energy: `75.6%`,
        price: `1,700 points`,
        locked: true
      },]
    }
  }
}
</script>

<style scoped lang="scss">

.vehicles {
  display: grid;
  grid-template-columns: 50% 50%;
  width: 100%;
  height: 100%;
  justify-content: center;
  align-items: center;
  overflow-y: auto;
  max-height: 700px;
}

.vehicle {
  display: flex;
  border: 2px solid $sago-dark;
  height: 220px;
  margin: 10px 10px;

  .stat {
    margin: 5px 0px;
    display: flex;
    align-items: center;
    font-size: 17px;
    font-weight: 300;

    .bx {
      margin-right: 5px;
      font-size: 25px;
    }
  }

  .info {
    flex: 0.6;
    display: grid;
    padding: 10px 0px 0px 30px;
    color: #fff;
    font-weight: 100;
  }

  .vehicle-name {
    color: #fff;
    font-size: 25px;
    font-weight: 300;
    word-break: break-all;
  }

  .join {
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 0.4;
  }

  .buyButton {
    background: none;
    border: 2px solid #2d6ae3;
    color: #fff;
    padding: 10px 30px;
    font-size: 20px;
    cursor: pointer;
    transition: background 0.4s;
    font-weight: 500;

    &:hover {
      background: #2d6ae3;
    }
  }

  .selectedButton {
    border: 2px solid #2de382 !important;
    background: #2de382 !important;

    &:hover {
      background: #2de382 !important;
    }
  }

  .selectButton {
    border: 2px solid #2de382 !important;

    &:hover {
      background: #2de382 !important;
    }
  }
}
</style>