<template>
  <div class="tab-content" v-show="title === selectedTitle">
    <slot/>
  </div>
</template>

<script>
import {inject} from 'vue';

export default {
  name: "LoadoutTab",
  props: ['title'],
  setup () {
    const selectedTitle = inject("selectedTitle")

    return {
      selectedTitle
    }
  }
}
</script>

<style scoped lang="scss">
.tab-content {
  width: 100%;
  height: 100%;
}
</style>