<template>
  <div class="loadouts">
    <div v-for="loadout in loadouts" :key="loadout.name" class="loadout" :style="{ background: 'linear-gradient(rgba(25, 23, 36, 0.9),rgba(25, 23, 36, 0.9)),  url(' + loadout.background + ') no-repeat center center', backgroundSize: 'cover' }">
      <div class="loadout-name">{{ loadout.name }}</div>
      <div v-if="loadout.requirements" class="loadout-reqs">
        <div v-for="req in loadout.requirements" :key="req" class="loadout-req">
          <i v-if="req.icon" class="req-icon" :class='req.icon'></i>
          <div v-if="req.text" class="req-text">{{ req.text }}</div>
        </div>
      </div>
      <div class="buttonArea">
        <button @click="selectBuy(loadout.name)" class="buyButton" :class="{ selectedButton: selectedLoadout === loadout.name, selectButton: !loadout.locked }" :disabled="selectedLoadout === loadout.name">
          <template v-if="selectedLoadout === loadout.name">
            Selected
          </template>
          <template v-else-if="loadout.locked">
            Buy
          </template>
          <template v-else>
            Select
          </template>
        </button>
      </div>
      <div class="loadout-info">
        <div v-for="weapon in loadout.weapons" :key="weapon.name" class="weapon">
          <img :src="weapon.img" :alt="weapon.name">
          <div v-if="weapon.ammo" class="ammo">{{ weapon.ammo }}</div>
          <div class="weapon-name">{{ weapon.name }}</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "FugitiveLoadouts",
  methods: {
    selectBuy(name) {
      // eslint-disable-next-line no-undef
      mp.trigger('MenuSelectLoadout', name, 0);
    },
  },
  data() {
    return {
      selectedLoadout: null,
      loadouts: [{
        name: 'Assassin',
        locked: true,
        background: 'https://i.imgur.com/EqsruXf.png',
        requirements: [
          {icon: "bx bxs-dollar-circle", text: "1200 points"},
          {icon: "fas fa-ruler", text: "Silver Donator"},
        ],
        weapons: [
          {
            name: "Pistol",
            img: "https://wiki.gtanet.work/images/thumb/9/9b/weapon_453432689.png/120px-weapon_453432689.png",
            ammo: 60,
          },
          {
            name: "Machete",
            img: "https://wiki.gtanet.work/images/thumb/a/a5/weapon_-581044007.png/120px-weapon_-581044007.png",
          }
        ],
      }]
    }
  }
}
</script>

<style scoped lang="scss">
.loadout-reqs {
  display: flex;
  justify-content: space-evenly;
  align-items: center;
  margin-bottom: 15px;

  .loadout-req {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    color: #fff;
    font-weight: 100;
    font-size: 15px;

    .req-icon {
      font-size: 30px;
      width: 100%;
      text-align: center;
      padding: 2px 0px;
    }
  }
}

.loadout-info {
  padding: 10px;
  display: grid;
  grid-template-columns: auto auto auto;
  align-items: center;
  justify-content: center;
  justify-items: center;
  align-content: center;
  grid-gap: 0px 20px;
  z-index: 50;
  color: #fff;
  font-weight: 100;
}

.weapon {
  display: flex;
  flex-direction: column;
  text-align: center;
  align-items: center;
  justify-content: center;
  justify-items: center;
  height: 100px;
  position: relative;

  .ammo {
    position: absolute;
    bottom: 30px;
    font-size: 12px;
  }
}

.loadouts {
  display: grid;
  grid-template-columns: 50% 50%;
  width: 100%;
  height: 100%;
  justify-content: center;
  align-items: start;
  overflow-y: auto;
  max-height: 730px;
}

.loadout {
  display: flex;
  border: 2px solid $sago-dark;
  //height: 250px;
  min-height: 250px;
  margin: 10px 10px;
  box-sizing: border-box;
  flex-direction: column;

  .stat {
    margin: 5px 0px;
    display: flex;
    align-items: center;
    font-size: 17px;
    font-weight: 300;

    .bx {
      margin-right: 5px;
      font-size: 25px;
    }
  }

  .loadout-name {
    color: #fff;
    font-size: 25px;
    font-weight: 300;
    word-break: break-all;
    text-align: center;
    padding: 5px;
  }

  .buttonArea {
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 0.25;
  }

  .buyButton {
    background: none;
    border: 2px solid #2d6ae3;
    color: #fff;
    padding: 5px 30px;
    font-size: 20px;
    cursor: pointer;
    transition: background 0.4s;
    font-weight: 500;

    &:hover {
      background: #2d6ae3;
    }
  }

  .selectedButton {
    border: 2px solid #2de382 !important;
    background: #2de382 !important;
  }

  .selectButton {
    border: 2px solid #2de382 !important;

    &:hover {
      background: #2de382 !important;
    }
  }
}
</style>